#Effacer une case d'un tableau

from numpy import *

t = array([int] * 10)


def Saisie():
    b = False
    while not b:
        n = int(input("Donner le nombre des cases: "))
        b = 5 <= n <= 20
    return n


def Remplir(n):
    for i in range(n):
        t[i] = int(input("t[" + str(i) + "] = "))


def Effacer(t, n):
    b = False
    while not b:
        p = int(input("Donner la position de la case à effacer: "))
        b = 0 <= p <= n
    for i in range(p, n - 1):
        t[i] = t[i + 1]
    n -= 1
    return n


def Afficher(t, n):
    for i in range(n):
        print(t[i])


####################PP####################

n = Saisie()
Remplir(n)
n = Effacer(t, n)
Afficher(t, n)
print(t)

